n reason: <?=e($target['ban_reason'])?></p><?php endif;?><?php if($target['is_admin']||$id===(int)$u['id']):?><p class="muted">This account is protected from status changes.</p><?php else:?><div class="user-admin-actions"><?php if($target['banned_at']):?><form method="post"><input type="hidden" name="action" value="user_unban"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button secondary">Remove permanent ban</button></form><?php else:?><form method="post"><input type="hidden" name="action" value="user_ban"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="ban_reason" value="Banned by administrator"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button danger">Permanent ban</button></form><?php if($target['disabled_at']):?><form method="post"><input type="hidden" name="action" value="user_enable"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button secondary">Enable account</button></form><?php else:?><form method="post"><input type="hidden" name="action" value="user_disable"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button danger">Disable account</button></form><?php endif;?><?php endif;?></div><?php endif;?></section>
